import { Toaster } from "@/components/ui/toaster";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter, Routes, Route } from "react-router-dom";

// --- PAGES (Generated by Lovable) ---
import Index from "./pages/Index"; 
import PatientHome from "./pages/PatientHome"; // The new Menu page
import PatientProfileASA from "./pages/PatientProfileASA";
import NotFound from "./pages/NotFound";

// --- COMPONENTS (Your existing logic) ---
import { MedicationScanner } from "./components/patient/MedicationScanner"; 
import { PatientList } from "./components/doctor/PatientList";
import { PatientFile } from "./components/doctor/PatientFile";
import { mockPatients } from "./lib/api"; 

const queryClient = new QueryClient();

const App = () => (
  <QueryClientProvider client={queryClient}>
    <BrowserRouter>
      <TooltipProvider>
        <Toaster />
        <Sonner />
        <Routes>
          {/* === PUBLIC ROUTES === */}
          <Route path="/" element={<Index />} />

          {/* === PATIENT ROUTES === */}
          {/* 1. The Home Menu */}
          <Route path="/patient" element={<PatientHome />} />
          <Route path="/patient/asa" element={<PatientProfileASA />} />
          
          {/* 2. The Scanner (Mapped to your specific component) */}
          <Route path="/patient/scanner" element={
            <div className="min-h-screen bg-slate-50">
               <MedicationScanner />
            </div>
          } />
          

          {/* 3. New Features */}


          {/* === DOCTOR ROUTES === */}
          {/* Kept your logic here to preserve PatientList/PatientFile functionality */}
          <Route path="/doctor" element={
            <div className="container mx-auto py-8 px-4">
              <h1 className="text-2xl font-bold mb-6 text-slate-800">Tableau de bord Médecin</h1>
              {/* Note: Ideally use useNavigate() hook inside PatientList instead of window.location */}
              <PatientList onSelectPatient={(p) => window.location.href = `/doctor/${p.id}`} />
            </div>
          } />

          <Route path="/doctor/:id" element={
            <div className="container mx-auto py-8 px-4">
              <PatientFile 
                patient={mockPatients[0]} 
                onBack={() => window.location.href = '/doctor'} 
              />
            </div>
          } />

          {/* === FALLBACK === */}
          <Route path="*" element={<NotFound />} />
        </Routes>
      </TooltipProvider>
    </BrowserRouter>
  </QueryClientProvider>
);

export default App;